jsonTools.css:
/* tools/eli_writer/style.css — the clause view ([CLAUSE-VIEW]): a change on a card or in a dialog, the same in every tool. */
/* [CARD-WORD] The clause's own words near-black. Every tracked change already in Word a quiet blue-grey, whoever made it — thin and
   quiet; ELI's proposal the card's focus: what it adds green on a soft green, what it strikes red on a soft red (the
   owner, 10-22). On Respond's card the change it's about is in its author's colour, no fill (10-23). */
.eli-clause { color: #0f172a; font-size: 14.5px; line-height: 1.55; }   /* [CARD-SIZE] the clause readable in the task pane (owner, 10-21); marks scale with it */
.eli-clause ._td_del, .eli-clause ._td_ins { text-decoration-thickness: 1px; }
.eli-clause ._td_del { text-decoration-line: line-through; }
.eli-clause ._td_ins { text-decoration-line: underline; text-underline-offset: 2px; }
.eli-clause ._td_other { color: #94a3b8; }   /* every revision already in Word a quiet blue-grey (the owner, 10-22: the blue was too blatant) */
.eli-clause ._td_other._td_struckins { text-decoration-line: underline line-through; text-decoration-color: currentColor; }
.eli-clause ._td_ins._td_prop { color: #15803d; background: #e8f6ec; border-radius: 0; text-decoration-color: #15803d; text-decoration-thickness: 1.5px; }
.eli-clause ._td_del._td_prop { color: #b42318; background: #fdecec; border-radius: 0; text-decoration-color: #b42318; text-decoration-thickness: 1.5px; }
.eli-clause ._td_prop ._td_ins._td_other { background: transparent; text-decoration-color: currentColor; }
/* the key: only what's already in Word, in its blue-grey (ELI's own green and red need none — the owner, 10-22) */
.eli-clause-key { display: flex; align-items: baseline; gap: 4px; margin: -4px 0 4px; font: 11px/1.3 Inter, "Segoe UI", system-ui, sans-serif; color: #64748b; }
.eli-clause-key-old { color: #94a3b8; }
.eli-clause ._td_other + ._td_prop, .eli-clause ._td_prop + ._td_other { margin-left: 0; }   /* the old mark and ELI's touching, as Word shows them (a gap read as a space before punctuation: the owner, 10-22) */
.eli-clause ._td_gap { color: #94a3b8; padding: 0 2px; }
/* [CARD-VIEW] who made a change already in Word, when it's tapped */
.eli-clause [data-eli-who] { cursor: pointer; }
.eli-clause-ctrls { display: flex; flex-wrap: wrap; justify-content: flex-end; align-items: center; gap: 6px; margin-top: 6px; }
.eli-clause-tog { white-space: nowrap; }
.eli-clause-ctrls .eli-clause-tog { height: auto; min-height: 0; box-shadow: none; border: 1px solid #b0bcc6; border-radius: 0; }
.eli-clause-tog { padding: 1px 8px; font: 600 11px/1.6 Inter, "Segoe UI", system-ui, sans-serif; text-transform: none; letter-spacing: 0; cursor: pointer; }
.eli-clause-other { margin-top: 6px; font: 12px/1.4 Inter, "Segoe UI", system-ui, sans-serif; color: #64748b; }
.eli-clause ._lk_b { font-weight: 700; }
.eli-clause ._lk_i { font-style: italic; }
.eli-clause ._lk_u { text-decoration-line: underline; }
/* [NEW-CLAUSE-CARD] a new clause: each of its paragraphs on a line of its own, ELI's green on a soft green */
.eli-clause-line + .eli-clause-line { margin-top: 5px; }
